import { Badge, Button, Card, Col, Divider, Row, Skeleton, Space, Tag, notification } from "antd";
import React, { useEffect, useRef, useState } from "react";
import Slider from "react-slick";
import "../../style/header.css";
import { FaHeart, FaRegHeart } from "react-icons/fa";
import { useNavigate, useParams } from "react-router-dom";
import { MdArrowRightAlt, MdKeyboardBackspace } from "react-icons/md";
import { useScreen } from "../auth/AuthScreen";
import { useDispatch, useSelector } from "react-redux";
import { addItem, removeItem, selectCartItems } from "../../redux/CartSlice";
import { useAuth } from "../auth/context/authContext";
import { AddProductWishlist, fetchBeforeCheckoutItem, FetchBrandProduct, out_of_stock } from "../apiService/api";
import DefaultImg from "../../assest/bkdlogo.png";

function BeforeCheckoutAllView() {
    const { id } = useParams();
  const { screenWidth } = useScreen()

    const { token, nearStore } = useAuth();
    const [productList, setProductList] = useState([]);
    const [loading, setLoading] = useState(false);
    const [current, setCurrent] = useState(1);
    const [noData, setNoData] = useState(false);
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const cartItems = useSelector(selectCartItems);
    const observerRef = useRef(null);
    const [wishlist, setWishlist] = useState({});
    const skeletonArray = new Array(productList?.length || screenWidth < 1400 ? 12 : 14).fill(0);


    const handleAddItem = (item) => {
        dispatch(addItem(item));
    };

    useEffect(() => {
        localStorage.setItem("cart", JSON.stringify(cartItems));
    }, [cartItems]);

    const handleDelItem = (item) => {
        dispatch(removeItem(item));
        const cart = JSON.parse(localStorage.getItem("cart")) || [];
        const updatedCart = cart.filter(cartItem => cartItem.productCode !== item.productCode);
        localStorage.setItem("cart", JSON.stringify(updatedCart));
    };

    const HnadleNotLogin = () => {
        notification.error({
            placement: "topRight",
            message: "Please login before add wishlist",
        });
    };

    const addToWishList = async (proCode) => {
        setWishlist((prev) => ({ ...prev, [proCode.productCode]: true })); // Immediately update the icon
        const body = { productCode: proCode.productCode, productName: proCode.productName, status: "ACTIVE" };
        try {
            await AddProductWishlist(token, body)
                .then((res) => {
                    if (res.status === 201) {
                        notification['success']({
                            placement: "topRight",
                            message: "Added Product To Wishlist",
                        });
                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setWishlist((prev) => ({ ...prev, [proCode]: false })); // Revert the icon if the API call fails
                    notification['error']({
                        placement: "topRight",
                        message: "Failed to Add Product To Wishlist",
                    });
                });
        } catch (error) {
            console.log(error);
            setWishlist((prev) => ({ ...prev, [proCode]: false })); // Revert the icon if the API call fails
        }
    };

    const RemoveToWishList = async (proCode) => {
        setWishlist((prev) => ({ ...prev, [proCode.productCode]: false })); // Immediately update the icon
        const body = { productCode: proCode.productCode, productName: proCode.productName, status: "INACTIVE" };
        try {
            await AddProductWishlist(token, body)
                .then((res) => {
                    if (res.status === 201) {
                        notification['warning']({
                            placement: "topRight",
                            message: "Removed Product From Wishlist",
                        });
                    }
                })
                .catch((err) => {
                    console.log(err.message);
                    setWishlist((prev) => ({ ...prev, [proCode]: true })); // Revert the icon if the API call fails
                    notification['error']({
                        placement: "topRight",
                        message: "Failed to Remove Product From Wishlist",
                    });
                });
        } catch (error) {
            console.log(error);
            setWishlist((prev) => ({ ...prev, [proCode]: true })); // Revert the icon if the API call fails
        }
    };


    const ShowBeforeCheckoutItem = async () => {
        setLoading(true);
        try {
            const res = await fetchBeforeCheckoutItem(nearStore?.branchCode);
            console.log("view before checkout", res);
            if (res.status === 200) {
                setProductList(prevData => [...prevData, ...res.data.data]);
                setNoData(res.data.data.length === 0);
            }
        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        ShowBeforeCheckoutItem();
    }, [current]);

    useEffect(() => {
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0].isIntersecting && !loading && !noData) {
                    setCurrent(prevPage => prevPage + 1);
                }
            },
            { threshold: 1.0 }
        );

        if (observerRef.current) {
            observer.observe(observerRef.current);
        }

        return () => {
            if (observerRef.current) {
                observer.unobserve(observerRef.current);
            }
        };
    }, [loading, noData]);
    const handleNotLogin = () => {
        notification.error({
            placement: "topRight",
            message: "Please login before adding to wishlist",
        });
    };

    return (
        <div className="show_pro">
            <div className="show_all_product">
                <Card
                    title={
                        <Space>
                            <Button type="link" onClick={() => navigate(-1)} icon={<MdKeyboardBackspace className="h4" />} />
                            <p>Explore Before Checkout </p>
                        </Space>
                    }
                    bordered={false}
                >
                    <div className={`${productList?.length !== 0 && "showing_pro_by_cat"}`}>
                        {!productList.length ? (
                            <div>

                                <div className="showing_pro_by_cat">
                                    {skeletonArray.map((_, index) => (
                                        <Card size="small" className="mx-2 mb-2" key={index}>
                                            <Skeleton.Image active />
                                            <Skeleton active paragraph={{ row: 6 }} />
                                        </Card>
                                    ))}
                                </div>

                            </div>
                        ) : (
                            productList.length === 0 ? (
                                <div className='text-center'>
                                    <img src="https://www.aamtrading.com/assets/img/nproduct.png" width="50%" />
                                </div>
                            ) : (
                                productList.map((item) => (
                                    <div className="product_card individual_card" key={item.productCode}>
                                        <Card hoverable disabled={item.stockQty === 0}>
                                            <div className="card_img">
                                                {item.imageUrl[0] ? (
                                                    <img
                                                        src={item.imageUrl[0] || DefaultImg}
                                                        onError={(e) => e.currentTarget.src = DefaultImg}
                                                        onClick={() => navigate(`/product/${item.productCode}`)}
                                                    />
                                                ) : (
                                                    <img src={DefaultImg} onClick={() => navigate(`/product/${item.productCode}`)} />
                                                )}
                                            </div>
                                            <div className="pro_name">
                                                <p>{item.productName}</p>
                                            </div>
                                            <div className="show_variant_item">
                                                {item.packSize && item.packSize !== "(NIL)" ? <Tag color="green">{item.packSize}</Tag> : <span className="hidden_data">N/A</span>}
                                                {item.stockQty <= out_of_stock && <Tag color='red' bordered={false}>out of stock</Tag>}
                                            </div>
                                            <div className="add_cart">
                                                <Space>
                                                    <p>{`₹ ${Math.round(item.bkdAmount)} `}</p>
                                                    {item.bkdAmount !== item.price && <p><del>₹ {item.price}</del></p>}
                                                </Space>
                                                {cartItems.find((cartItem) => cartItem.productCode === item.productCode) ? (
                                                    cartItems.map((cartItem) => {
                                                        if (cartItem.productCode === item.productCode) {
                                                            return (
                                                                <Button.Group size='small' key={cartItem.productCode}>
                                                                    <Button onClick={() => handleDelItem(item)}>-</Button>
                                                                    <Button>{cartItem.unit}</Button>
                                                                    <Button onClick={() => handleAddItem(item)}>+</Button>
                                                                </Button.Group>
                                                            );
                                                        }
                                                        return null;
                                                    })
                                                ) : (
                                                    <Button disabled={item.stockQty <= out_of_stock} type="default" onClick={() => handleAddItem(item)}>Add</Button>
                                                )}
                                            </div>
                                        </Card>
                                        {item.bkdAmount !== item.price && (
                                            <div className="cat_tags">
                                                {Math.round((item.price - item.bkdAmount) * 100 / item.price)}% off
                                            </div>
                                        )}
                                        <div className="wish_list">
                                            {token ?
                                                <div className='wish_list'>
                                                    {
                                                        wishlist[item.productCode] || item.isWhislist ? (
                                                            <FaHeart
                                                                className="no_wish_icon"
                                                                size={22}
                                                                color='red'
                                                                onClick={() => RemoveToWishList(item)}
                                                            />
                                                        ) : (
                                                            <FaRegHeart
                                                                className="no_wish_icon"
                                                                size={22}
                                                                onClick={() => addToWishList(item)}
                                                            />
                                                        )
                                                    }
                                                </div>

                                                :
                                                <div className='wish_list'>
                                                    <FaRegHeart
                                                        className="no_wish_icon"
                                                        size={22}
                                                        onClick={handleNotLogin}
                                                    />
                                                </div>
                                            }
                                        </div>
                                    </div>
                                ))
                            )
                        )}
                    </div>
                    <div ref={observerRef}>
                        {loading && (
                            <div className="showing_pro_by_cat">
                                {skeletonArray.map((_, index) => (
                                    <Card size="small" className="mx-2 mb-2" key={index}>
                                        <Skeleton.Image active />
                                        <Skeleton active paragraph={{ row: 6 }} />
                                    </Card>
                                ))}
                            </div>
                        )}
                    </div>

                </Card>
            </div>
        </div>
    );
}



export default BeforeCheckoutAllView
